select.if:
SELECT * FROM (
UNION ALL
) ORDER BY tradeDateText DESC

mapper.sql:
SELECT 'root' parentId/*树形表格父节点ID*/, T1.TOTLE_TRADE_ID||'_'||#{status_02} childId /*树形表格子节点ID*/, T1.TOTLE_TRADE_ID totleTradeId /*交易编号*/, CASE WHEN T1.TRADE_STATUS = #{TRADE_STATUS_01} THEN #{status_02} WHEN T1.TRADE_STATUS = #{TRADE_STATUS_03} THEN #{status_03} ELSE '' END validStatus /*有效状态*/, TO_CHAR(T1.TRADE_DATE,'yyyy-MM-dd') tradeDateText /*交易日期*/, T2.COUNTER_ID counter_id, /* add by songyawei */ T2.COUNTER_NAME counterId /*交易对手*/, T1.COUNTER_TRADER counterTrader /*对手方交易员*/, T1.PS ps /*交易方向*/, T1.TRADE_AMT tradeAmt /*交易金额*/, NVL(T1.RATE, 0) * 100 rate /*回购利率*/, T1.REPO_TERM repoTerm /*回购期限（天）*/, T1.SETTLE_SPEED settleSpeedText /*清算速度*/, T1.DELIVERY_TYPE deliveryType /*首期结算方式*/, T1.M_DELIVERY_TYPE mDeliveryType /*到期结算方式*/, T1.CLEAR_TYPE clearType /*清算类型*/, TO_CHAR(T1.EFF_TIME,'yyyy-MM-dd HH24:mi:ss') effTime /*有效时间*/, T1.REMARK remark /*补充条款*/, T3.SEC_ACCT_ID secAcctId /*托管账号*/, T3.REGIST_ORG registOrg /*托管机构名称*/, T3.SEC_ACCT_NAME secAcctName /*托管账户户名*/, T4.BUSI_ACCT_NO acctNo /*账户*/, T4.ACCT_NAME acctName /*户名*/, T4.BANK_DEP acctBankDep /*资金开户行*/, T4.LARGE_PAYNO acctBankDepoPayno /*资金开户行支付系统行号*/, 'CNY' bondCcy /*债券币种*/, 'CNY' settleCcy /*结算币种*/, '' workflowId, '' workflowStatus ,T1.PORTFOLIO_ID portfolioId /* add by songyawei */ FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN MST_COUNTER_PARTY T2 ON T1.COUNTER_ID = T2.COUNTER_ID LEFT JOIN STL_SEC_ACCT_INFO T3 ON T1.SEC_MANAGE_ACCT_ID = T3.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO T4 ON T3.TRD_ACCT_ID = T4.ACCT_NO AND T3.TRD_ACCT_CCY = T4.CCY WHERE T1.BUSI_TYPE = #{COMMON_BUSINESS_TYPE_TRD70} AND T1.IS_CANCEL = #{IS_CANCEL_N}
AND T1.TRADE_STATUS = #{TRADE_STATUS_01}
AND T1.TRADE_STATUS = #{TRADE_STATUS_03}
AND (T1.TRADE_STATUS = #{TRADE_STATUS_01} OR T1.TRADE_STATUS = #{TRADE_STATUS_03})
AND EXISTS ( SELECT 1 FROM TRD_PRODUCT_DEAL_PRE TPD, TRD_PRODUCT_DEAL_ADD_PRE TPDA WHERE TPD.TRADE_ID = TPDA.TRADE_ID AND TPD.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND TPDA.PORTFOLIO_ID IN ( SELECT PPA.PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY PPA WHERE PPA.USER_ID = #{loginUserName} ) )

mapper.select:
 select s.sec_acct_id secAcctId,s.sec_acct_name secAcctName,s.regist_org registOrg
from STL_SEC_ACCT_INFO S

 where sec_acct_id=#{ourdepositaccountnumber}
